# Cloakroom hook launcher for PowerShell (Windows without Git Bash): hook.ps1 start|prompt|pre|post, hook JSON on
# stdin. Runs the cloakroom program if it is installed; otherwise answers for it and starts the installer.
# Generated by scripts/gen_hooks.py in the cloakroom repository; edit that file, not this one.
param([string]$E)
# UTF-8 without a byte-order mark: Windows PowerShell 5.1's [Text.Encoding]::UTF8 adds one to piped input
$u = New-Object System.Text.UTF8Encoding $false; [Console]::InputEncoding = $u; [Console]::OutputEncoding = $u; $OutputEncoding = $u
switch ($E) {
  'start' { $inst = '{"systemMessage": "cloakroom: installing itself (one time). Rules-only protection starts in about a minute, the full model follows in a few minutes. Tool calls are held back until then; progress in ~/.cloakroom/bootstrap.log. To stop it: turn off the cloakroom plugin in /plugin."}'
    $noinst = '{"systemMessage": "cloakroom: not installed, and nothing to install it with (no curl, wget, uv, pipx or Python 3.10+). To finish: 1. Install curl (Linux: sudo apt install curl on Ubuntu/Debian, sudo dnf install curl on Fedora/RHEL) or uv (Mac: brew install uv). 2. Then restart Claude Code (/exit, then claude) and Cloakroom installs itself. Log: ~/.cloakroom/bootstrap.log. Tool calls are held back until then. To stop it: turn off the cloakroom plugin in /plugin."}'
    $failed = '{"systemMessage": "cloakroom: the automatic install failed; it tries again in 10 minutes. To finish: 1. Read the error at the end of ~/.cloakroom/bootstrap.log. 2. Fix it, or install Cloakroom yourself (command: https://github.com/shanjeevrajendran/cloakroom#get-started). 3. Then restart Claude Code (/exit, then claude). Log: ~/.cloakroom/bootstrap.log. Tool calls are held back until then. To stop it: turn off the cloakroom plugin in /plugin."}'
    $offline = '{"systemMessage": "cloakroom: the automatic install failed; it tries again in 10 minutes. It could not reach the internet. To finish: 1. Connect to the internet (behind a proxy or firewall, allow astral.sh, releases.astral.sh, pypi.org, files.pythonhosted.org and huggingface.co). 2. Then restart Claude Code (/exit, then claude). Log: ~/.cloakroom/bootstrap.log. Tool calls are held back until then. To stop it: turn off the cloakroom plugin in /plugin."}'
    $checksum = '{"systemMessage": "cloakroom: the automatic install failed; it tries again in 10 minutes. The uv installer from astral.sh did not match its pinned checksum, so it was not run. To finish: 1. Install uv yourself (Mac: brew install uv; Windows: winget install astral-sh.uv; Linux: https://docs.astral.sh/uv/getting-started/installation/, or on Ubuntu/Debian sudo apt install python3-venv instead). 2. Then restart Claude Code (/exit, then claude). Log: ~/.cloakroom/bootstrap.log. Tool calls are held back until then. To stop it: turn off the cloakroom plugin in /plugin."}'
    $updating = '{"systemMessage": "cloakroom: updating itself to the new plugin version (about a minute). Tool calls are held back until then; progress in ~/.cloakroom/bootstrap.log. To stop it: turn off the cloakroom plugin in /plugin."}' }
  'prompt' { $inst = '{"systemMessage": "cloakroom: installing itself (one time). Rules-only protection starts in about a minute, the full model follows in a few minutes. Tool calls are held back until then; progress in ~/.cloakroom/bootstrap.log. To stop it: turn off the cloakroom plugin in /plugin.", "hookSpecificOutput": {"hookEventName": "UserPromptSubmit", "additionalContext": "The Cloakroom privacy plugin is enabled but its program is not ready yet (installing or updating), so every tool call is denied until it is. Tell the user what the Cloakroom message says if they ask why tools are blocked."}}'
    $noinst = '{"systemMessage": "cloakroom: not installed, and nothing to install it with (no curl, wget, uv, pipx or Python 3.10+). To finish: 1. Install curl (Linux: sudo apt install curl on Ubuntu/Debian, sudo dnf install curl on Fedora/RHEL) or uv (Mac: brew install uv). 2. Then restart Claude Code (/exit, then claude) and Cloakroom installs itself. Log: ~/.cloakroom/bootstrap.log. Tool calls are held back until then. To stop it: turn off the cloakroom plugin in /plugin.", "hookSpecificOutput": {"hookEventName": "UserPromptSubmit", "additionalContext": "The Cloakroom privacy plugin is enabled but its program is not ready yet (installing or updating), so every tool call is denied until it is. Tell the user what the Cloakroom message says if they ask why tools are blocked."}}'
    $failed = '{"systemMessage": "cloakroom: the automatic install failed; it tries again in 10 minutes. To finish: 1. Read the error at the end of ~/.cloakroom/bootstrap.log. 2. Fix it, or install Cloakroom yourself (command: https://github.com/shanjeevrajendran/cloakroom#get-started). 3. Then restart Claude Code (/exit, then claude). Log: ~/.cloakroom/bootstrap.log. Tool calls are held back until then. To stop it: turn off the cloakroom plugin in /plugin.", "hookSpecificOutput": {"hookEventName": "UserPromptSubmit", "additionalContext": "The Cloakroom privacy plugin is enabled but its program is not ready yet (installing or updating), so every tool call is denied until it is. Tell the user what the Cloakroom message says if they ask why tools are blocked."}}'
    $offline = '{"systemMessage": "cloakroom: the automatic install failed; it tries again in 10 minutes. It could not reach the internet. To finish: 1. Connect to the internet (behind a proxy or firewall, allow astral.sh, releases.astral.sh, pypi.org, files.pythonhosted.org and huggingface.co). 2. Then restart Claude Code (/exit, then claude). Log: ~/.cloakroom/bootstrap.log. Tool calls are held back until then. To stop it: turn off the cloakroom plugin in /plugin.", "hookSpecificOutput": {"hookEventName": "UserPromptSubmit", "additionalContext": "The Cloakroom privacy plugin is enabled but its program is not ready yet (installing or updating), so every tool call is denied until it is. Tell the user what the Cloakroom message says if they ask why tools are blocked."}}'
    $checksum = '{"systemMessage": "cloakroom: the automatic install failed; it tries again in 10 minutes. The uv installer from astral.sh did not match its pinned checksum, so it was not run. To finish: 1. Install uv yourself (Mac: brew install uv; Windows: winget install astral-sh.uv; Linux: https://docs.astral.sh/uv/getting-started/installation/, or on Ubuntu/Debian sudo apt install python3-venv instead). 2. Then restart Claude Code (/exit, then claude). Log: ~/.cloakroom/bootstrap.log. Tool calls are held back until then. To stop it: turn off the cloakroom plugin in /plugin.", "hookSpecificOutput": {"hookEventName": "UserPromptSubmit", "additionalContext": "The Cloakroom privacy plugin is enabled but its program is not ready yet (installing or updating), so every tool call is denied until it is. Tell the user what the Cloakroom message says if they ask why tools are blocked."}}'
    $updating = '{"systemMessage": "cloakroom: updating itself to the new plugin version (about a minute). Tool calls are held back until then; progress in ~/.cloakroom/bootstrap.log. To stop it: turn off the cloakroom plugin in /plugin.", "hookSpecificOutput": {"hookEventName": "UserPromptSubmit", "additionalContext": "The Cloakroom privacy plugin is enabled but its program is not ready yet (installing or updating), so every tool call is denied until it is. Tell the user what the Cloakroom message says if they ask why tools are blocked."}}' }
  'pre' { $inst = '{"hookSpecificOutput": {"hookEventName": "PreToolUse", "permissionDecision": "deny", "permissionDecisionReason": "Cloakroom blocked this tool call: installing itself (one time). Rules-only protection starts in about a minute, the full model follows in a few minutes. Tool calls are held back until then; progress in ~/.cloakroom/bootstrap.log. To stop it: turn off the cloakroom plugin in /plugin."}}'
    $noinst = '{"hookSpecificOutput": {"hookEventName": "PreToolUse", "permissionDecision": "deny", "permissionDecisionReason": "Cloakroom blocked this tool call: not installed, and nothing to install it with (no curl, wget, uv, pipx or Python 3.10+). To finish: 1. Install curl (Linux: sudo apt install curl on Ubuntu/Debian, sudo dnf install curl on Fedora/RHEL) or uv (Mac: brew install uv). 2. Then restart Claude Code (/exit, then claude) and Cloakroom installs itself. Log: ~/.cloakroom/bootstrap.log. Tool calls are held back until then. To stop it: turn off the cloakroom plugin in /plugin."}}'
    $failed = '{"hookSpecificOutput": {"hookEventName": "PreToolUse", "permissionDecision": "deny", "permissionDecisionReason": "Cloakroom blocked this tool call: the automatic install failed; it tries again in 10 minutes. To finish: 1. Read the error at the end of ~/.cloakroom/bootstrap.log. 2. Fix it, or install Cloakroom yourself (command: https://github.com/shanjeevrajendran/cloakroom#get-started). 3. Then restart Claude Code (/exit, then claude). Log: ~/.cloakroom/bootstrap.log. Tool calls are held back until then. To stop it: turn off the cloakroom plugin in /plugin."}}'
    $offline = '{"hookSpecificOutput": {"hookEventName": "PreToolUse", "permissionDecision": "deny", "permissionDecisionReason": "Cloakroom blocked this tool call: the automatic install failed; it tries again in 10 minutes. It could not reach the internet. To finish: 1. Connect to the internet (behind a proxy or firewall, allow astral.sh, releases.astral.sh, pypi.org, files.pythonhosted.org and huggingface.co). 2. Then restart Claude Code (/exit, then claude). Log: ~/.cloakroom/bootstrap.log. Tool calls are held back until then. To stop it: turn off the cloakroom plugin in /plugin."}}'
    $checksum = '{"hookSpecificOutput": {"hookEventName": "PreToolUse", "permissionDecision": "deny", "permissionDecisionReason": "Cloakroom blocked this tool call: the automatic install failed; it tries again in 10 minutes. The uv installer from astral.sh did not match its pinned checksum, so it was not run. To finish: 1. Install uv yourself (Mac: brew install uv; Windows: winget install astral-sh.uv; Linux: https://docs.astral.sh/uv/getting-started/installation/, or on Ubuntu/Debian sudo apt install python3-venv instead). 2. Then restart Claude Code (/exit, then claude). Log: ~/.cloakroom/bootstrap.log. Tool calls are held back until then. To stop it: turn off the cloakroom plugin in /plugin."}}'
    $updating = '{"hookSpecificOutput": {"hookEventName": "PreToolUse", "permissionDecision": "deny", "permissionDecisionReason": "Cloakroom blocked this tool call: updating itself to the new plugin version (about a minute). Tool calls are held back until then; progress in ~/.cloakroom/bootstrap.log. To stop it: turn off the cloakroom plugin in /plugin."}}' }
  'post' { $inst = '{"hookSpecificOutput": {"hookEventName": "PostToolUse", "updatedToolOutput": "[Cloakroom blocked this tool call: installing itself (one time). Rules-only protection starts in about a minute, the full model follows in a few minutes. Tool calls are held back until then; progress in ~/.cloakroom/bootstrap.log. To stop it: turn off the cloakroom plugin in /plugin.]"}}'
    $noinst = '{"hookSpecificOutput": {"hookEventName": "PostToolUse", "updatedToolOutput": "[Cloakroom blocked this tool call: not installed, and nothing to install it with (no curl, wget, uv, pipx or Python 3.10+). To finish: 1. Install curl (Linux: sudo apt install curl on Ubuntu/Debian, sudo dnf install curl on Fedora/RHEL) or uv (Mac: brew install uv). 2. Then restart Claude Code (/exit, then claude) and Cloakroom installs itself. Log: ~/.cloakroom/bootstrap.log. Tool calls are held back until then. To stop it: turn off the cloakroom plugin in /plugin.]"}}'
    $failed = '{"hookSpecificOutput": {"hookEventName": "PostToolUse", "updatedToolOutput": "[Cloakroom blocked this tool call: the automatic install failed; it tries again in 10 minutes. To finish: 1. Read the error at the end of ~/.cloakroom/bootstrap.log. 2. Fix it, or install Cloakroom yourself (command: https://github.com/shanjeevrajendran/cloakroom#get-started). 3. Then restart Claude Code (/exit, then claude). Log: ~/.cloakroom/bootstrap.log. Tool calls are held back until then. To stop it: turn off the cloakroom plugin in /plugin.]"}}'
    $offline = '{"hookSpecificOutput": {"hookEventName": "PostToolUse", "updatedToolOutput": "[Cloakroom blocked this tool call: the automatic install failed; it tries again in 10 minutes. It could not reach the internet. To finish: 1. Connect to the internet (behind a proxy or firewall, allow astral.sh, releases.astral.sh, pypi.org, files.pythonhosted.org and huggingface.co). 2. Then restart Claude Code (/exit, then claude). Log: ~/.cloakroom/bootstrap.log. Tool calls are held back until then. To stop it: turn off the cloakroom plugin in /plugin.]"}}'
    $checksum = '{"hookSpecificOutput": {"hookEventName": "PostToolUse", "updatedToolOutput": "[Cloakroom blocked this tool call: the automatic install failed; it tries again in 10 minutes. The uv installer from astral.sh did not match its pinned checksum, so it was not run. To finish: 1. Install uv yourself (Mac: brew install uv; Windows: winget install astral-sh.uv; Linux: https://docs.astral.sh/uv/getting-started/installation/, or on Ubuntu/Debian sudo apt install python3-venv instead). 2. Then restart Claude Code (/exit, then claude). Log: ~/.cloakroom/bootstrap.log. Tool calls are held back until then. To stop it: turn off the cloakroom plugin in /plugin.]"}}'
    $updating = '{"hookSpecificOutput": {"hookEventName": "PostToolUse", "updatedToolOutput": "[Cloakroom blocked this tool call: updating itself to the new plugin version (about a minute). Tool calls are held back until then; progress in ~/.cloakroom/bootstrap.log. To stop it: turn off the cloakroom plugin in /plugin.]"}}' }
  default { [Console]::Error.WriteLine('usage: hook.ps1 start|prompt|pre|post'); exit 2 }
}
$h = if ($env:CLOAKROOM_HOME) { $env:CLOAKROOM_HOME } else { Join-Path $env:USERPROFILE '.cloakroom' }
$pin = '0.6.6'
# the program: on PATH, in ~/.local/bin (where the installers put it) or in ~/.cloakroom/venv
$cr = (Get-Command cloakroom -ErrorAction SilentlyContinue).Source
foreach ($c in @((Join-Path $env:USERPROFILE '.local\bin\cloakroom.exe'), (Join-Path $h 'venv\Scripts\cloakroom.exe'))) {
  if (-not $cr -and (Test-Path $c)) { $cr = $c }
}
# a failed install retries after 10 minutes, not on every call
$st = Join-Path $h 'bootstrap.state'
$recent = (Test-Path $st) -and ((Get-Content $st -ErrorAction SilentlyContinue) -eq 'failed') -and
  (((Get-Date) - (Get-Item $st).LastWriteTime).TotalMinutes -lt 10)
$boot = Join-Path $env:CLAUDE_PLUGIN_ROOT 'scripts\bootstrap.ps1'
$bargs = '-NoProfile','-ExecutionPolicy','Bypass','-File',('"' + $boot + '"')
$ps = if ($PSVersionTable.PSEdition -eq 'Core') { 'pwsh' } else { 'powershell' }
# an upgrade is swapping the program's files (Windows can't replace files in use): answer for it, never start the
# old program (a hold older than 30 minutes is stale)
$hold = Join-Path $h 'bootstrap.lock\upgrade'
if ((Test-Path $hold) -and (((Get-Date) - (Get-Item $hold).LastWriteTime).TotalMinutes -lt 30)) { $updating }
elseif ($cr) {
  # the plugin was updated: upgrade in the background, keep running the installed program meanwhile
  $sf = Join-Path $h 'upgrade.stamp'
  $s = if (Test-Path $sf) { (Get-Content $sf -TotalCount 1 -ErrorAction SilentlyContinue) -join '' } else { '' }
  if ($s -ne $pin -and -not (Test-Path (Join-Path $h 'bootstrap.lock')) -and
      ($s -ne "failed:$pin" -or ((Get-Date) - (Get-Item $sf).LastWriteTime).TotalMinutes -ge 10)) {
    Start-Process $ps -WindowStyle Hidden -ArgumentList ($bargs + '-Upgrade') | Out-Null
  }
  # steps the user must take to upgrade (left by the installer): once, at a session start
  $nf = Join-Path $h 'upgrade.notice'
  if ($E -eq 'start' -and (Test-Path $nf)) {
    [Console]::In.ReadToEnd() | & $cr hook $E | Out-Null; Get-Content $nf -Raw; Remove-Item -Force $nf
  }
  else { [Console]::In.ReadToEnd() | & $cr hook $E }
}
elseif ($recent) {  # the installer leaves the reason for the steps
  switch ((Get-Content (Join-Path $h 'bootstrap.reason') -ErrorAction SilentlyContinue) -join '') {
    'offline' { $offline }
    'checksum' { $checksum }
    default { $failed }
  }
}
else {
  & $boot -Check
  if ($LASTEXITCODE -eq 0) {
    Start-Process $ps -WindowStyle Hidden -ArgumentList $bargs | Out-Null
    $inst
  }
  else { $noinst }
}
exit 0
